@startuml

class Employee {
  + Name : string
  + SocialSecurityNumber : string
  + HasOscar : boolean
}

class CreativeEmployee extends Employee {}

class Director extends CreativeEmployee {
  + AssistantName : string
}

class Actor extends CreativeEmployee {
  + Education : string
}

class Technician extends Employee {
  + FieldOfActivity : string
}

class Location {
  + Name : string
}

class Film {
  + Title : string
  + YearOfRelease : int
}

enum Genre {
  THRILLER
  ACTION
  HORROR
  COMEDY
}

class Screenwriter {
  + Name : string
  + MostSuccessfulFilm : string
}

class Screenplay {
  + Title : string
  + Version : string
  + Date : date
  + NumberOfScenes : int
  + Plot : string
}

class Novel {
  + Title : string
  + Author : string
}

class Concept {}

Film "*" -- "*" Location

Film "1" -- "1" Genre

Screenwriter "1" -- "*" Screenplay

Screenplay "1" -- "1" Film

Screenplay "1" -- "0..1" Novel
Screenplay "1" -- "0..1" Concept

Actor "*" -- "1" Screenplay : reads
Director "1" -- "1" Screenplay : implements

@enduml

